package main

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// projectConfig is generated by `levier init` so each project keeps its own
// App identity, runtime, and MCP references. It contains locators, not keys.
type projectConfig struct {
	AppName     string `json:"app_name,omitempty"`
	Credentials string `json:"credentials,omitempty"`
	Server      string `json:"server,omitempty"`
	Runtime     string `json:"runtime,omitempty"`
	MCPRefs     string `json:"mcp_refs,omitempty"`
}

func projectConfigPath() string {
	workingDir, err := os.Getwd()
	if err != nil {
		return ""
	}
	return filepath.Join(workingDir, ".levier.json")
}

func loadProjectConfig() projectConfig {
	path := projectConfigPath()
	if path == "" {
		return projectConfig{}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return projectConfig{}
	}
	var config projectConfig
	if json.Unmarshal(data, &config) != nil {
		return projectConfig{}
	}
	return config
}

func saveProjectConfig(config projectConfig) error {
	path := projectConfigPath()
	if path == "" {
		return nil
	}
	data, err := json.MarshalIndent(config, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return os.WriteFile(path, data, 0o600)
}
